// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) public {
        vm.assume(caller != address(0));
        bool before = c.approvedToLog(caller);
        vm.prank(caller);
        bool returned = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        assertTrue(returned == before);
    }
}

